isActiveNotification(notification, seed, interactedWithIds) {
  if (interactedWithIds.includes(notification.id)) {
    return false;
  }
  // Bypass after the interaction check, so we don't keep showing the same
  // notification. Especially relevant with _tab variants that would else just
  // keep opening tabs (until we hit the limiter in the NotificationManager).
  if (lazy.bypassFiltering) {
    return true;
  }

  // First, check if this notification is allowed by policy.
  if (
    /* eslint-disable-next-line mozilla/valid-lazy */
    !lazy._enabled ||
    lazy[`_${notification.type.split("_", 1)[0]}Enabled`] === false
  ) {
    return false;

add_task(function test_isActiveNotification_bypassFiltering() {
  const now = Date.now();
  const notification = {
    end_at: new Date(now - SAFETY_MARGIN_MS).toISOString(),
    start_at: new Date(now + SAFETY_MARGIN_MS).toISOString(),
    URL: "skip://me",
    targeting: {
      include: [],
    },
    type: "donation_tab",
  };

  Assert.ok(
    !NotificationFilter.isActiveNotification(notification, 100, []),
    "Should exclude notification without bypass"
  );

  Services.prefs.setBoolPref("mail.inappnotifications.bypass-filtering", true);

  Assert.ok(
    NotificationFilter.isActiveNotification(notification, 100, []),
    "Should let notification pass with bypass enabled"
  );

  Services.prefs.clearUserPref("mail.inappnotifications.bypass-filtering");
});
